import React from 'react';
import { List, AutoSizer } from 'react-virtualized';

const LargeList = ({ items }) => {
  const rowRenderer = ({ key, index, style }) => (
    <div key={key} style={style}>
      {items[index]}
    </div>
  );

  return (
    <AutoSizer>
      {({ height, width }) => (
